bool register_godot_classes(LhatProgram *program, Godot *module)
{
    // The base is always earlier in the table than what is declared
    // under it, since a chain is walked from its root.
    for (BoundClass &owner : classes) {
        owner.tag =
            owner.base == nullptr
                ? lhat_register_hostdata_type(program, "godot",
                                              owner.name)
                : lhat_register_hostdata_subtype(program, "godot",
                                                 owner.name, "godot",
                                                 owner.base);
        if (owner.tag == nullptr) {
            return false;
        }
        module->tags.insert(StringName(owner.name), owner.tag);
    }
    return true;
}

bool register_godot_api(LhatProgram *program, Godot *module)
{
    for (BoundMethod &method : bound) {
        // 8.7 makes the module the process's, so a bind is found
        // once however many programs are registered into.
        if (method.module == nullptr) {
            method.module = module;
            StringName owner(method.class_name);
            StringName named(method.name);
            method.bind =
                internal::gdextension_interface_classdb_get_method_bind(
                    owner._native_ptr(), named._native_ptr(),
                    (GDExtensionInt)method.hash);
        }
        if (!lhat_register_member(program, "godot",
                                  method.class_name, method.name,
                                  method.signature, bound_call,
                                  &method)) {
            return false;
        }
    }
    return true;
}

